/* ===== ShiftWise — Shared Stylesheet ===== */

:root {
  --blue: #0051C3;
  --blue-dark: #003d96;
  --blue-light: #e8f0fc;
  --red: #DE5052;
  --red-dark: #c43a3c;
  --white: #ffffff;
  --gray-50: #f8f9fb;
  --gray-100: #f1f3f7;
  --gray-200: #e4e8f0;
  --gray-300: #c8d0df;
  --gray-400: #9aa5b8;
  --gray-500: #6b7694;
  --gray-600: #4a5568;
  --gray-700: #2d3748;
  --gray-800: #1a202c;
  --gray-900: #0f1623;
  --radius: 12px;
  --radius-sm: 8px;
  --radius-lg: 20px;
  --shadow: 0 2px 12px rgba(0,81,195,0.08);
  --shadow-md: 0 8px 32px rgba(0,81,195,0.12);
  --shadow-lg: 0 20px 60px rgba(0,81,195,0.16);
  --transition: 0.2s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', system-ui, sans-serif;
  color: var(--gray-800);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }

a { text-decoration: none; color: inherit; }

/* ===== LAYOUT ===== */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.section-pad { padding: 96px 0; }
.bg-light { background: var(--gray-50); }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  border: 2px solid transparent;
  transition: all var(--transition);
  white-space: nowrap;
  text-decoration: none;
}

.btn-primary {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.btn-primary:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(222,80,82,0.35);
}

.btn-outline {
  background: transparent;
  color: var(--blue);
  border-color: var(--blue);
}
.btn-outline:hover {
  background: var(--blue);
  color: var(--white);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: var(--gray-700);
  border-color: transparent;
}
.btn-ghost:hover { color: var(--blue); }

.btn-white {
  background: var(--white);
  color: var(--blue);
  border-color: var(--white);
}
.btn-white:hover {
  background: var(--blue-light);
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(255,255,255,0.3);
}

.btn-lg { padding: 16px 32px; font-size: 16px; border-radius: var(--radius); }
.w-full { width: 100%; }

/* ===== HEADER ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}
.site-header.scrolled { box-shadow: var(--shadow-md); }

.header-inner {
  display: flex;
  align-items: center;
  gap: 32px;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 800;
  font-size: 20px;
  color: var(--blue);
  flex-shrink: 0;
}
.logo-icon { font-size: 22px; }

.desktop-nav {
  display: flex;
  gap: 4px;
  margin-left: auto;
}

.nav-link {
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 500;
  color: var(--gray-600);
  transition: all var(--transition);
}
.nav-link:hover { color: var(--blue); background: var(--blue-light); }
.nav-link.active { color: var(--blue); font-weight: 600; }

.header-cta {
  display: flex;
  gap: 8px;
  margin-left: 16px;
}

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  margin-left: auto;
}
.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--gray-700);
  border-radius: 2px;
  transition: all var(--transition);
}
.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* ===== MOBILE NAV ===== */
.mobile-nav-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 200;
  opacity: 0;
  transition: opacity var(--transition);
}
.mobile-nav-overlay.visible { opacity: 1; }

.mobile-nav {
  position: fixed;
  top: 0;
  right: -320px;
  width: 300px;
  height: 100vh;
  background: var(--white);
  z-index: 300;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  transition: right 0.3s ease;
  box-shadow: -8px 0 40px rgba(0,0,0,0.15);
}
.mobile-nav.open { right: 0; }

.mobile-nav-close {
  align-self: flex-end;
  background: none;
  border: none;
  font-size: 20px;
  cursor: pointer;
  color: var(--gray-600);
  padding: 4px;
  margin-bottom: 12px;
}

.mobile-nav-link {
  padding: 14px 16px;
  border-radius: var(--radius-sm);
  font-size: 16px;
  font-weight: 500;
  color: var(--gray-700);
  transition: all var(--transition);
  border-bottom: 1px solid var(--gray-100);
}
.mobile-nav-link:hover { color: var(--blue); background: var(--blue-light); }

.mobile-nav-cta {
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-top: 20px;
  border-top: 1px solid var(--gray-200);
}

/* ===== SECTION HEADER ===== */
.section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 64px;
}

.section-tag {
  display: inline-block;
  background: var(--blue-light);
  color: var(--blue);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 14px;
  border-radius: 100px;
  margin-bottom: 16px;
}

.section-title {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(28px, 4vw, 40px);
  font-weight: 800;
  color: var(--gray-900);
  line-height: 1.2;
  margin-bottom: 16px;
}

.section-subtitle {
  font-size: 17px;
  color: var(--gray-500);
  line-height: 1.65;
}

/* ===== HERO ===== */
.hero-section {
  background: linear-gradient(135deg, #0f1e3d 0%, #0d2d6e 40%, #0051C3 100%);
  color: var(--white);
  padding: 80px 0 0;
  overflow: hidden;
}

.hero-badge {
  display: inline-block;
  background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.2);
  color: rgba(255,255,255,0.9);
  font-size: 14px;
  font-weight: 500;
  padding: 8px 18px;
  border-radius: 100px;
  margin-bottom: 28px;
}

.hero-title {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(32px, 5vw, 60px);
  font-weight: 900;
  line-height: 1.1;
  margin-bottom: 24px;
  max-width: 820px;
}

.accent-text { color: #FF7B6B; }

.hero-subtitle {
  font-size: clamp(16px, 2vw, 19px);
  color: rgba(255,255,255,0.8);
  max-width: 620px;
  margin-bottom: 36px;
  line-height: 1.65;
}

.hero-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}

.hero-actions .btn-outline {
  color: var(--white);
  border-color: rgba(255,255,255,0.4);
}
.hero-actions .btn-outline:hover {
  background: rgba(255,255,255,0.15);
  color: var(--white);
  border-color: rgba(255,255,255,0.6);
}

.hero-footnote {
  font-size: 13px;
  color: rgba(255,255,255,0.5);
  margin-bottom: 64px;
}

/* Dashboard Mockup */
.hero-visual { padding-bottom: 0; }

.dashboard-mockup {
  background: var(--white);
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  max-width: 760px;
  margin: 0 auto;
}

.mockup-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 20px;
  background: var(--gray-800);
  color: var(--white);
}
.mockup-dots { display: flex; gap: 6px; }
.mockup-dots span {
  width: 12px; height: 12px; border-radius: 50%;
}
.mockup-dots span:nth-child(1) { background: #ff5f57; }
.mockup-dots span:nth-child(2) { background: #febc2e; }
.mockup-dots span:nth-child(3) { background: #28c840; }
.mockup-title { font-size: 14px; font-weight: 500; color: var(--gray-300); flex: 1; text-align: center; }
.mockup-status { display: flex; align-items: center; gap: 6px; font-size: 13px; }
.status-dot { width: 8px; height: 8px; border-radius: 50%; background: #28c840; animation: pulse 2s infinite; }

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.mockup-schedule { padding: 20px; }

.schedule-header {
  display: grid;
  grid-template-columns: 140px repeat(5, 1fr);
  gap: 6px;
  margin-bottom: 10px;
}
.sch-label, .sch-day {
  font-size: 12px;
  font-weight: 700;
  color: var(--gray-500);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  text-align: center;
}
.sch-label { text-align: left; }

.schedule-row {
  display: grid;
  grid-template-columns: 140px repeat(5, 1fr);
  gap: 6px;
  margin-bottom: 8px;
  align-items: center;
}

.sch-name {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  font-weight: 600;
  color: var(--gray-700);
}

.avatar {
  width: 28px; height: 28px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 10px; font-weight: 700; color: var(--white);
  flex-shrink: 0;
}
.av-1 { background: #0051C3; }
.av-2 { background: #DE5052; }
.av-3 { background: #059669; }
.av-4 { background: #7c3aed; }

.sch-shift {
  padding: 6px 4px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 600;
  text-align: center;
}
.shift-morning { background: #dbeafe; color: #1d4ed8; }
.shift-evening { background: #fce7f3; color: #be185d; }
.shift-off { background: var(--gray-100); color: var(--gray-400); }

.mockup-footer {
  display: flex;
  gap: 24px;
  padding: 16px 20px;
  background: var(--gray-50);
  border-top: 1px solid var(--gray-200);
}
.mockup-stat { display: flex; flex-direction: column; }
.mstat-label { font-size: 11px; color: var(--gray-500); font-weight: 500; }
.mstat-val { font-size: 18px; font-weight: 800; color: var(--gray-900); }
.mstat-val.green { color: #059669; }

/* ===== STATS ===== */
.stats-section {
  background: var(--blue);
  padding: 64px 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  text-align: center;
}

.stat-item { color: var(--white); }

.stat-number {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(32px, 4vw, 52px);
  font-weight: 900;
  line-height: 1;
  margin-bottom: 8px;
}

.stat-label {
  font-size: 14px;
  color: rgba(255,255,255,0.7);
  font-weight: 500;
}

/* ===== FEATURES ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.feature-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius);
  padding: 32px;
  transition: all var(--transition);
}
.feature-card:hover {
  border-color: var(--blue);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.feature-icon {
  font-size: 32px;
  margin-bottom: 16px;
  display: block;
}

.feature-card h3 {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 18px;
  font-weight: 700;
  color: var(--gray-900);
  margin-bottom: 10px;
}

.feature-card p {
  font-size: 15px;
  color: var(--gray-500);
  line-height: 1.6;
}

.feature-card-cta {
  background: var(--blue-light);
  border-color: var(--blue);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 16px;
}
.feature-card-cta h3 { color: var(--blue); }
.feature-card-cta p { color: var(--gray-600); }

/* ===== HOW IT WORKS ===== */
.steps-grid {
  display: grid;
  grid-template-columns: 1fr auto 1fr auto 1fr auto 1fr;
  gap: 0;
  align-items: start;
}

.step-item { text-align: center; padding: 0 16px; }

.step-number {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 48px;
  font-weight: 900;
  color: var(--blue);
  line-height: 1;
  margin-bottom: 16px;
  opacity: 0.15;
}

.step-item h3 {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 18px;
  font-weight: 700;
  color: var(--gray-900);
  margin-bottom: 10px;
}
.step-item p { font-size: 15px; color: var(--gray-500); }

.step-connector {
  width: 40px;
  height: 2px;
  background: var(--gray-200);
  margin-top: 28px;
  flex-shrink: 0;
}

/* ===== TESTIMONIALS ===== */
.testimonials-carousel { max-width: 720px; margin: 0 auto; }

.testimonials-track { position: relative; min-height: 200px; }

.testimonial-card {
  display: none;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 40px 48px;
  box-shadow: var(--shadow);
}
.testimonial-card.active { display: block; animation: fadeIn 0.4s ease; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

.testimonial-stars { color: #f59e0b; font-size: 18px; margin-bottom: 20px; letter-spacing: 2px; }

.testimonial-card blockquote {
  font-size: clamp(17px, 2vw, 20px);
  color: var(--gray-800);
  font-style: italic;
  line-height: 1.6;
  margin-bottom: 28px;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 14px;
}
.author-avatar {
  width: 48px; height: 48px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px; font-weight: 700; color: var(--white);
  flex-shrink: 0;
}
.testimonial-author strong { display: block; font-size: 16px; color: var(--gray-900); }
.testimonial-author span { font-size: 14px; color: var(--gray-500); }

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 28px;
}

.carousel-btn {
  width: 44px; height: 44px;
  border-radius: 50%;
  border: 2px solid var(--gray-200);
  background: var(--white);
  font-size: 18px;
  cursor: pointer;
  transition: all var(--transition);
  display: flex; align-items: center; justify-content: center;
  color: var(--gray-600);
}
.carousel-btn:hover { border-color: var(--blue); color: var(--blue); background: var(--blue-light); }

.carousel-dots { display: flex; gap: 8px; }
.dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.dot.active { background: var(--blue); transform: scale(1.3); }

/* ===== PRICING TEASER ===== */
.pricing-teaser-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  align-items: start;
}

.pt-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius);
  padding: 32px;
  position: relative;
}

.pt-card-featured {
  border-color: var(--blue);
  box-shadow: var(--shadow-md);
  transform: translateY(-8px);
}

.pt-badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--red);
  color: var(--white);
  font-size: 12px;
  font-weight: 700;
  padding: 4px 14px;
  border-radius: 100px;
  white-space: nowrap;
}

.pt-plan {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 18px;
  font-weight: 800;
  color: var(--gray-900);
  margin-bottom: 8px;
}

.pt-price {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 40px;
  font-weight: 900;
  color: var(--blue);
  margin-bottom: 6px;
  line-height: 1;
}
.pt-price span { font-size: 16px; font-weight: 500; color: var(--gray-400); }

.pt-desc { font-size: 14px; color: var(--gray-500); margin-bottom: 24px; }

.pt-features {
  list-style: none;
  margin-bottom: 28px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.pt-features li {
  font-size: 14px;
  color: var(--gray-600);
  display: flex;
  align-items: center;
  gap: 6px;
}
.pt-features li:has(✗) { color: var(--gray-300); }

.pricing-teaser-note {
  text-align: center;
  margin-top: 32px;
  font-size: 14px;
  color: var(--gray-500);
}
.pricing-teaser-note a { color: var(--blue); font-weight: 600; }
.pricing-teaser-note a:hover { text-decoration: underline; }

/* ===== CTA SECTION ===== */
.cta-section {
  background: linear-gradient(135deg, #0f1e3d 0%, #0051C3 100%);
  padding: 96px 0;
}

.cta-inner {
  text-align: center;
  max-width: 680px;
  margin: 0 auto;
}
.cta-inner h2 {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(28px, 4vw, 42px);
  font-weight: 900;
  color: var(--white);
  margin-bottom: 16px;
  line-height: 1.2;
}
.cta-inner p {
  font-size: 18px;
  color: rgba(255,255,255,0.75);
  margin-bottom: 36px;
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--gray-900);
  color: var(--white);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand .logo { margin-bottom: 12px; }
.footer-brand .logo-text { color: var(--white); }
.footer-brand p { font-size: 14px; color: var(--gray-400); line-height: 1.6; margin-bottom: 16px; }

.footer-contact-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 13px;
  color: var(--gray-400);
}

.footer-col h4 {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gray-400);
  margin-bottom: 16px;
}
.footer-col a {
  display: block;
  font-size: 14px;
  color: var(--gray-400);
  margin-bottom: 10px;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid var(--gray-700);
  padding-top: 24px;
  text-align: center;
  font-size: 13px;
  color: var(--gray-500);
}

/* ===== PAGE HERO (inner pages) ===== */
.page-hero {
  background: linear-gradient(135deg, #0f1e3d 0%, #0d2d6e 50%, #0051C3 100%);
  padding: 80px 0;
  color: var(--white);
  text-align: center;
}
.page-hero h1 {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 900;
  margin-bottom: 16px;
  line-height: 1.2;
}
.page-hero p {
  font-size: 18px;
  color: rgba(255,255,255,0.8);
  max-width: 580px;
  margin: 0 auto 28px;
  line-height: 1.65;
}

/* ===== FEATURES PAGE ===== */
.feature-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
  padding: 80px 0;
  border-bottom: 1px solid var(--gray-100);
}
.feature-row:last-of-type { border-bottom: none; }
.feature-row.reverse { direction: rtl; }
.feature-row.reverse > * { direction: ltr; }

.feature-row-text h2 {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(24px, 3vw, 36px);
  font-weight: 800;
  color: var(--gray-900);
  margin-bottom: 16px;
  line-height: 1.2;
}
.feature-row-text p {
  font-size: 16px;
  color: var(--gray-500);
  line-height: 1.7;
  margin-bottom: 24px;
}
.feature-row-text ul {
  list-style: none;
