/* ===== PRICING PAGE ===== */
.pricing-toggle-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 56px;
}
.billing-label {
  font-size: 15px;
  font-weight: 600;
  color: var(--gray-600);
  transition: color var(--transition);
}
.billing-label.active { color: var(--blue); }

.toggle-switch {
  position: relative;
