  border-radius: 100px;
  cursor: pointer;
  border: none;
  transition: background var(--transition);
}
.toggle-switch.on { background: var(--blue); }
.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--white);
