}

.faq-question {
  width: 100%;
  background: none;
  border: none;
  padding: 22px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  font-size: 16px;
  font-weight: 600;
  color: var(--gray-900);
  cursor: pointer;
  text-align: left;
  transition: background var(--transition);
}
.faq-question:hover { background: var(--gray-50); }
.faq-question.open { color: var(--blue); }

.faq-chevron {
  flex-shrink: 0;
  font-size: 18px;
  transition: transform var(--transition);
  color: var(--gray-400);
}
.faq-question.open .faq-chevron { transform: rotate(45deg); color: var(--blue); }

.faq-answer {
  display: none;
  padding: 0 24px 22px;
  font-size: 15px;
  color: var(--gray-500);
  line-height: 1.7;
}
.faq-answer.open { display: block; animation: fadeIn 0.25s ease; }

/* ===== ABOUT PAGE ===== */
.mission-section { padding: 96px 0; }
.mission-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.mission-text h2 {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(26px, 3vw, 38px);
  font-weight: 800;
  color: var(--gray-900);
  margin-bottom: 20px;
  line-height: 1.25;
}
.mission-text p {
  font-size: 16px;
  color: var(--gray-500);
