}
.mission-quote {
  font-size: 20px;
  font-weight: 700;
  line-height: 1.5;
}

/* Team */
.team-section { padding: 96px 0; background: var(--gray-50); }
.team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.team-card {
  background: var(--white);
