}

.cta-inner {
  text-align: center;
  max-width: 680px;
  margin: 0 auto;
}
.cta-inner h2 {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(28px, 4vw, 42px);
  font-weight: 900;
  color: var(--white);
  margin-bottom: 16px;
  line-height: 1.2;
}
.cta-inner p {
  font-size: 18px;
  color: rgba(255,255,255,0.75);
  margin-bottom: 36px;
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--gray-900);
  color: var(--white);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand .logo { margin-bottom: 12px; }
.footer-brand .logo-text { color: var(--white); }
.footer-brand p { font-size: 14px; color: var(--gray-400); line-height: 1.6; margin-bottom: 16px; }

.footer-contact-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 13px;
  color: var(--gray-400);
}

.footer-col h4 {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gray-400);
  margin-bottom: 16px;
}
.footer-col a {
  display: block;
  font-size: 14px;
  color: var(--gray-400);
  margin-bottom: 10px;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid var(--gray-700);
  padding-top: 24px;
  text-align: center;
  font-size: 13px;
  color: var(--gray-500);
}

/* ===== PAGE HERO (inner pages) ===== */
.page-hero {
  background: linear-gradient(135deg, #0f1e3d 0%, #0d2d6e 50%, #0051C3 100%);
  padding: 80px 0;
  color: var(--white);
  text-align: center;
}
.page-hero h1 {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 900;
  margin-bottom: 16px;
  line-height: 1.2;
}
.page-hero p {
  font-size: 18px;
  color: rgba(255,255,255,0.8);
  max-width: 580px;
  margin: 0 auto 28px;
  line-height: 1.65;
}

/* ===== FEATURES PAGE ===== */
.feature-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
  padding: 80px 0;
  border-bottom: 1px solid var(--gray-100);
}
.feature-row:last-of-type { border-bottom: none; }
.feature-row.reverse { direction: rtl; }
.feature-row.reverse > * { direction: ltr; }

.feature-row-text h2 {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(24px, 3vw, 36px);
  font-weight: 800;
  color: var(--gray-900);
  margin-bottom: 16px;
  line-height: 1.2;
}
.feature-row-text p {
  font-size: 16px;
  color: var(--gray-500);
  line-height: 1.7;
  margin-bottom: 24px;
}
.feature-row-text ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.feature-row-text li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 15px;
  color: var(--gray-600);
}
.feature-row-text li::before {
  content: '✓';
  color: var(--blue);
  font-weight: 700;
  flex-shrink: 0;
  margin-top: 1px;
}

.feature-visual {
  background: var(--gray-50);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  min-height: 280px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 80px;
  flex-direction: column;
  gap: 16px;
}
.feature-visual-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--gray-400);
  text-align: center;
}

/* Integrations grid */
.integrations-section { background: var(--gray-50); padding: 96px 0; }

.integrations-categories {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-bottom: 48px;
}

.integration-cat {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius);
  padding: 28px 24px;
  text-align: center;
}

.integration-cat-icon { font-size: 40px; margin-bottom: 12px; }
.integration-cat h3 {
  font-size: 16px;
  font-weight: 700;
  color: var(--gray-900);
  margin-bottom: 12px;
}
.integration-cat ul { list-style: none; display: flex; flex-direction: column; gap: 6px; }
.integration-cat li { font-size: 13px; color: var(--gray-500); }

/* ===== PRICING PAGE ===== */
.pricing-toggle-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 56px;
}
.billing-label {
  font-size: 15px;
  font-weight: 600;
  color: var(--gray-600);
  transition: color var(--transition);
}
.billing-label.active { color: var(--blue); }

.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--gray-200);
  border-radius: 100px;
  cursor: pointer;
  border: none;
  transition: background var(--transition);
}
.toggle-switch.on { background: var(--blue); }
.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--white);
  transition: transform var(--transition);
  box-shadow: 0 2px 6px rgba(0,0,0,0.2);
}
.toggle-switch.on::after { transform: translateX(24px); }

.annual-badge {
  background: #dcfce7;
  color: #166534;
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 100px;
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  align-items: start;
  margin-bottom: 64px;
}

.pricing-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 36px;
  position: relative;
  transition: all var(--transition);
}
.pricing-card:hover { box-shadow: var(--shadow-md); }
.pricing-card.featured {
  border-color: var(--blue);
  box-shadow: var(--shadow-md);
  transform: translateY(-10px);
}

.pricing-badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--red);
  color: var(--white);
  font-size: 12px;
  font-weight: 700;
  padding: 5px 16px;
  border-radius: 100px;
}

.pricing-plan-name {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 22px;
  font-weight: 800;
  color: var(--gray-900);
  margin-bottom: 6px;
}
.pricing-plan-desc { font-size: 14px; color: var(--gray-400); margin-bottom: 24px; }

.pricing-price-block { margin-bottom: 28px; }
.price-amount {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 48px;
  font-weight: 900;
  color: var(--gray-900);
  line-height: 1;
}
.price-amount .currency { font-size: 24px; vertical-align: top; margin-top: 8px; display: inline-block; }
.price-amount .period { font-size: 16px; font-weight: 500; color: var(--gray-400); }
.price-orig { font-size: 14px; color: var(--gray-400); text-decoration: line-through; margin-top: 4px; }

.pricing-cta-btn { width: 100%; margin-bottom: 32px; }

.pricing-feature-label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gray-400);
  margin-bottom: 14px;
}

.pricing-features-list { list-style: none; display: flex; flex-direction: column; gap: 12px; }
.pricing-features-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  color: var(--gray-600);
}
.feat-check { color: #059669; font-weight: 700; flex-shrink: 0; }
.feat-x { color: var(--gray-300); flex-shrink: 0; }
.feat-partial { color: var(--gray-500); flex-shrink: 0; }

/* FAQ */
.faq-section { padding: 96px 0; background: var(--gray-50); }

.faq-list { max-width: 720px; margin: 0 auto; display: flex; flex-direction: column; gap: 4px; }

.faq-item {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius);
  overflow: hidden;
}

.faq-question {
  width: 100%;
  background: none;
  border: none;
  padding: 22px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  font-size: 16px;
  font-weight: 600;
  color: var(--gray-900);
  cursor: pointer;
  text-align: left;
  transition: background var(--transition);
}
.faq-question:hover { background: var(--gray-50); }
.faq-question.open { color: var(--blue); }

.faq-chevron {
